"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3267],{8219(e){e.exports=JSON.parse('{"title":"Tooltip\uc740 \uc815\ub9d0 \uc88b\uc740 UX\uc778\uac00?","date":"2025-11-26","coverUrl":"/kudzu-based-bench/assets/notion/e33e50fabc107a54.png","html":"<h1 data-notion-block-id=\\"2afe548d-8a8e-8092-b743-c9febe59dc53\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2b5e548d-8a8e-80a4-9f26-f93d04f5782d\\" id=\\"2b5e548d-8a8e-80a4-9f26-f93d04f5782d\\">Tooltip\uc740 \uc815\ub9d0 \uc88b\uc740 UX\uc778\uac00?</h2><a href=\\"https://tkdodo.eu/blog/tooltip-components-should-not-exist\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/tooltip-components-should-not-exist</a><p data-notion-block-id=\\"2b5e548d-8a8e-80a3-af01-d21efd65b46d\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/132e548d-8a8e-80db-a33c-f4337d20c800#132e548d-8a8e-8016-859c-d19cc51c08f6\\">Tooltip\uc744 \uc798 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95</a>\uacfc \ube44\uc2b7\ud558\uac8c, \ubcf4\ud1b5\uc758 \uacbd\uc6b0 tooltip\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 UX\ub97c \ud574\uce58\uba70, \ub610\ud55c \uad6c\ud604 \ubc29\ubc95\uc744 \ub2e4\ub974\uac8c, \ud639\uc740 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc740 UX\ub97c \uc704\ud55c \uac83\uc774\ub77c\uace0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/427a9c3c-eab8-4c52-b1c8-9036c2552ded#5305d247-0b9f-4962-b1dd-aa921534dbf4\\">Toast\ub294 \uc815\ub9d0 \uc88b\uc740 UX\uc778\uac00?</a>\uc640 <a href=\\"https://primer.style/accessibility/toasts/#what-to-use-instead-of-toasts\\">Github \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 Toast deprecate \uc18c\uc2dd</a>\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2b5e548d-8a8e-80f1-bd00-c15746d8dec7\\" id=\\"2b5e548d-8a8e-80f1-bd00-c15746d8dec7\\">e18e\uc758 tinyglobby \uc131\uacfc \uacf5\uc720</h2><a href=\\"https://e18e.dev/blog/tinyglobby-migration.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://e18e.dev/blog/tinyglobby-migration.html</a><p data-notion-block-id=\\"2afe548d-8a8e-80e8-ada0-e121f334ac9f\\">JavaScript \uc0dd\ud0dc\uacc4\uc758 \uc131\ub2a5\uc744 \ub192\uc774\ub294 \ucee4\ubba4\ub2c8\ud2f0\uc778 <a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70\\">e18e</a>\uc5d0\uc11c <code>globby</code>\uc640 <code>fast-glob</code>\uc744 \ub300\uccb4\ud558\ub294 <code>tinyglobby</code>\ub97c \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc801\uc6a9\ud574\uc11c \uc5b4\ub5a4 \uc131\uacfc\ub97c \ub0c8\ub294\uc9c0, \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 \ube44\uad50\ud574\uc11c \uc5b4\ub5a4 \uc810\uc774 \uc88b\uc740\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9cc\uc57d <code>globby</code>\uc640 <code>fast-glob</code>\ub97c \uc544\uc9c1\ub3c4 \uc0ac\uc6a9\ud558\uace0 \uacc4\uc2e0\ub2e4\uba74 <code>tinyglobby</code>\ub97c \uace0\ub824\ud574\ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"2b5e548d-8a8e-80aa-8090-e5fff5554043\\" id=\\"2b5e548d-8a8e-80aa-8090-e5fff5554043\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 \uc784\ud329\ud2b8 \uce21\uc815\ud558\uae30</h2><a href=\\"https://didoo.medium.com/measuring-the-impact-of-a-design-system-7f925af090f7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://didoo.medium.com/measuring-the-impact-of-a-design-system-7f925af090f7</a><p data-notion-block-id=\\"2b7e548d-8a8e-8090-9234-dbe71008ead4\\">Uber\uc758 <a href=\\"https://www.uber.com/en-KR/blog/design-system-at-scale/\\">\ub514\uc790\uc778\uc2dc\uc2a4\ud15c\uc758 \uc0ac\uc6a9\ub7c9 \uce21\uc815</a> \ube14\ub85c\uadf8\uc640 \ube44\uc2b7\ud558\uac8c, \ub514\uc790\uc778\uc2dc\uc2a4\ud15c\uc5d0 \uac1c\ubc1c\uc5d0\uc11c \uac1c\ubc1c\uc5d0 \uac00\uc838\ub2e4 \uc900 \uc784\ud329\ud2b8\ub97c \uc5b4\ub5bb\uac8c \uce21\uc815\ud588\uace0, \ucf54\ub4dc \ubcc0\uacbd \ube48\ub3c4\uac00 \uc5b4\ub5bb\uac8c \uc904\uc5b4\ub4e4\uc5c8\ub294\uc9c0\ub85c \uc784\ud329\ud2b8\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2b7e548d-8a8e-80c6-9ddd-d69fb257fb2e\\" id=\\"2b7e548d-8a8e-80c6-9ddd-d69fb257fb2e\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub85c\ub9cc \ub3d9\uc791\ud558\uae30\ub294 \uc5b4\ub835\ub2e4.</h2><a href=\\"https://pedrocattori.com/posts/just-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pedrocattori.com/posts/just-javascript/</a><p data-notion-block-id=\\"2afe548d-8a8e-80d2-8e09-df754add6c88\\">\ucd5c\uadfc\uc5d0\ub294 JSX\ub098,  TypeScript\uac19\uc740 \ud2b8\ub79c\uc2a4\ud30c\uc77c\ub7ec\ub098, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae30\ub2a5\ub4e4(HMR, \ub77c\uc6b0\ud305, \u2026)\uc73c\ub85c \ubcf4\uc5ec\uc9c0\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub85c\ub9cc \ub3d9\uc791\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac04\ub2e8\ud55c \uc5d0\uc138\uc774\uc785\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \uc0ac\uc6a9\ud558\ub294\ub370\uc5d0 \ud070 \ubb38\uc81c\ub294 \uc5c6\uc9c0\ub9cc, \ub4a4\uc5d0\uc11c \uc774\ub7ec\ud55c \ub3d9\uc791\uc774 \uc788\uace0, \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc744 \uac00\uc838\uc624\ub294\uc9c0\ub294 \uc778\uc9c0\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2afe548d-8a8e-8043-b8ce-c830af885f45\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2b7e548d-8a8e-80d1-a6ab-c6285c9bbe98\\" id=\\"2b7e548d-8a8e-80d1-a6ab-c6285c9bbe98\\">Electron \ub300\uc2e0 Tauri\ub97c \uc37c\uc744 \ub54c.</h2><a href=\\"https://www.dolthub.com/blog/2025-11-13-electron-vs-tauri/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.dolthub.com/blog/2025-11-13-electron-vs-tauri/</a><p data-notion-block-id=\\"2b0e548d-8a8e-80b8-a5ea-d2f9b844f688\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa#1d3e548d-8a8e-8065-9c6e-ef3c5a7a556f\\">Electron\uacfc Tauri\uc758 \uc544\ud0a4\ud14d\uccd0 \ucc28\uc774\uc810</a>\uacfc \ube44\uc2b7\ud558\uac8c \ucc28\uc774\uc810\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc774\uc9c0\ub9cc, \uc774 \uae00\uc740 \uc2e4\uc81c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud574\ubcf4\uace0 Tauri\uc5d0 \uc5b4\ub5a4 \uc7a5\uc810\uc774 \uc788\ub294\uc9c0, \ud558\uc9c0\ub9cc \uc5b4\ub5a4 blocking point\uac00 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2b0e548d-8a8e-8024-abd5-f4d5362b853e\\" id=\\"2b0e548d-8a8e-8024-abd5-f4d5362b853e\\">Vitest\uc758 browser mode \uc0b4\ud3b4\ubcf4\uae30</h2><a href=\\"https://www.epicweb.dev/vitest-browser-mode-vs-playwright\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicweb.dev/vitest-browser-mode-vs-playwright</a><p data-notion-block-id=\\"2b2e548d-8a8e-802c-b561-ea2d74e43752\\">Vitest\uc758 browser mode\uc758 \ubaa9\uc801\uc740 \ubb34\uc5c7\uc778\uc9c0, Playwright\uc640 \ubb34\uc2a8 \ucc28\uc774\uac00 \uc788\ub294\uc9c0 \uce5c\uc808\ud558\uac8c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd94\uac00\ub85c \ub0b4\uc6a9\uc5d0 \ub4e4\uc5b4\uc788\ub294 <a href=\\"https://ui.toast.com/posts/ko_20220624\\">JSDOM\uc740 \uc9c4\uc9dc DOM\uc774 \uc544\ub2c8\ub2e4</a>\ub97c \ub354 \uc77d\uc5b4\ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2b7e548d-8a8e-802d-8a29-d947e0668b7e\\" id=\\"2b7e548d-8a8e-802d-8a29-d947e0668b7e\\">\ud6a8\uacfc\uc801\uc778 \uc811\uadfc\uc131 label\uc740?</h2><a href=\\"https://www.tpgi.com/accessible-names-and-labels-understanding-what-works-and-what-doesnt/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.tpgi.com/accessible-names-and-labels-understanding-what-works-and-what-doesnt/</a><p data-notion-block-id=\\"2afe548d-8a8e-80c1-a63e-d4b8b55b0b85\\">label\uc744 \ub2e4\uc591\ud55c \ubc29\uc2dd\uc73c\ub85c \uc0ac\uc6a9\ud560 \ub54c, \uc5b4\ub5a4 \uc2dc\ub098\ub9ac\uc624\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubc29\uc2dd\uc774 \ud6a8\uacfc\uac00 \uc88b\uc740\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2b5e548d-8a8e-80bc-aca5-f1de76a26d56\\" id=\\"2b5e548d-8a8e-80bc-aca5-f1de76a26d56\\">Baseline\uc740 \uce5c\uc808\ud558\uc9c0 \uc54a\ub2e4.</h2><a href=\\"https://piccalil.li/blog/perfecting-baseline/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/perfecting-baseline/</a><p data-notion-block-id=\\"2b5e548d-8a8e-80d0-b58f-f4ad420620fd\\"><a href=\\"https://web.dev/baseline\\">Baseline</a>\uc758 \uc6a9\uc5b4\uac00 \uc5b4\ub5a4 \uc758\ubbf8\ub97c \ub744\uace0 \uc788\uc73c\uba70, \uc5b4\ub5a4 \ub178\ub825\uc744 \ud558\uace0 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9cc\uc57d Baseline\uc5d0 \uad00\uc2ec\uc774 \uc788\ub2e4\uba74 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"2b5e548d-8a8e-8061-b41f-d2a8a9e78815\\" id=\\"2b5e548d-8a8e-8061-b41f-d2a8a9e78815\\">Browserlist\uc5d0\uc11c Baseline\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://frontendmasters.com/blog/browserslist-baseline/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/browserslist-baseline/</a><h2 data-notion-block-id=\\"2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\" id=\\"2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\">\ub2a6\uc740 \uc18c\uc2dd\uc774\uc9c0\ub9cc, JS\uc5c6\uc774 Modal\uc744 \uad6c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://laktek.com/modal-dialogs-without-react-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://laktek.com/modal-dialogs-without-react-javascript</a><h1 data-notion-block-id=\\"2afe548d-8a8e-8025-8a5c-df29c86c3e8f\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://www.prisma.io/blog/announcing-prisma-orm-7-0-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.prisma.io/blog/announcing-prisma-orm-7-0-0</a><p data-notion-block-id=\\"2b5e548d-8a8e-801a-9a45-d5fa86be769f\\">\ud074\ub77c\uc774\uc5b8\ud2b8 \ubd80\ubd84\uc5d0\uc11c Rust\ub97c \uc5c6\uc564 \uba54\uc774\uc800 \uc5c5\ub370\uc774\ud2b8\uc785\ub2c8\ub2e4. \ubc88\ub4e4 \ud06c\uae30\uc758 90%\ub97c \uc904\uc600\uace0 \uc18d\ub3c4\ub3c4 \ube68\ub77c\uc84c\ub2e4\uace0 \ud558\ub124\uc694.</p><a href=\\"https://blog.angular.dev/announcing-angular-v21-57946c34f14b\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.angular.dev/announcing-angular-v21-57946c34f14b</a><p data-notion-block-id=\\"2b5e548d-8a8e-8063-9780-dac34b41f5b8\\">Signal\uc744 Form\uc5d0\uc11c \ub354 \uac15\ub825\ud558\uac8c \uc4f8 \uc218 \uc788\ub294 Signal Forms\ub97c \uc2e4\ud5d8\uc801\uc73c\ub85c \ub3c4\uc785\ud558\uace0, Zone.js \uc5c6\ub294(Zoneless) \uac1c\ubc1c \ud658\uacbd\uc744 \uc548\uc815\ud654\ud588\uc2b5\ub2c8\ub2e4. \ucd94\uac00\ub85c AI\ub97c \uc704\ud574 MCP \uc11c\ubc84\ub3c4 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"2b5e548d-8a8e-8072-8c97-f6a4bdc4f5e9\\" id=\\"2b5e548d-8a8e-8072-8c97-f6a4bdc4f5e9\\">\ubc88\uc678: Cloudflare tunnel \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://david.coffee/cloudflare-zero-trust-tunnels\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://david.coffee/cloudflare-zero-trust-tunnels</a><p data-notion-block-id=\\"2b5e548d-8a8e-8065-8b28-d3a6b0ab76a0\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \ud06c\uac8c \uad00\ub828\uc774 \uc5c6\uc9c0\ub9cc, \uc0ac\uc774\ub4dc \ud504\ub85c\uc81d\ud2b8\ub97c \uc9c4\ud589\ud560 \uacbd\uc6b0 \uc798 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 Cloudflare tunnel\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 Tailscale\uacfc\ub294 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);